ALTER TABLE "document_versions" DROP CONSTRAINT "document_versions_status_check";--> statement-breakpoint
ALTER TABLE "document_versions" DROP CONSTRAINT "document_versions_review_metadata_check";--> statement-breakpoint
ALTER TABLE "document_versions" ALTER COLUMN "status" SET DEFAULT 'draft';--> statement-breakpoint
ALTER TABLE "document_versions" ADD CONSTRAINT "document_versions_status_check" CHECK ("document_versions"."status" in ('draft', 'in_review', 'approved', 'rejected'));--> statement-breakpoint
ALTER TABLE "document_versions" ADD CONSTRAINT "document_versions_review_metadata_check" CHECK (("document_versions"."status" = 'draft' AND "document_versions"."reviewed_by_collaborator_id" IS NULL AND "document_versions"."reviewed_at" IS NULL AND "document_versions"."rejection_reason" IS NULL) OR ("document_versions"."status" = 'in_review' AND "document_versions"."reviewed_by_collaborator_id" IS NULL AND "document_versions"."reviewed_at" IS NULL AND "document_versions"."rejection_reason" IS NULL) OR ("document_versions"."status" = 'approved' AND "document_versions"."reviewed_by_collaborator_id" IS NOT NULL AND "document_versions"."reviewed_at" IS NOT NULL AND "document_versions"."rejection_reason" IS NULL) OR ("document_versions"."status" = 'rejected' AND "document_versions"."reviewed_by_collaborator_id" IS NOT NULL AND "document_versions"."reviewed_at" IS NOT NULL AND "document_versions"."rejection_reason" IS NOT NULL AND length(btrim("document_versions"."rejection_reason")) > 0));